  async function loadStream(stream, size, name, key, label) {
    stop();
    $('src').textContent = 'Reading ' + name + '...';
    const bar = $('progress'); bar.hidden = false; const fill = bar.firstElementChild;
    const parser = makeParser();
    let done = 0, rest = '';
    const reader = stream.getReader();
    const dec = new TextDecoder();
    for (;;) {
      const { value, done: end } = await reader.read();
      if (end) break;
      done += value.byteLength;
      const chunk = rest + dec.decode(value, { stream: true });
      const lines = chunk.split('\n'); rest = lines.pop();
      for (const l of lines) parser.line(l);
      fill.style.width = (100 * done / Math.max(1, size)).toFixed(1) + '%';
      await new Promise((r) => setTimeout(r, 0));
    }
    parser.line(rest + dec.decode());
    bar.hidden = true;
    parser.out.sort((a, b) => (a.ts && b.ts ? (a.ts < b.ts ? -1 : a.ts > b.ts ? 1 : 0) : 0));
    fileKey = key; loadStars();
    setData(parser.out, label, false);
  }

