  function makeParser() {
    const out = [];
    const seen = new Set();
    const toolNames = new Map();
    const toolInputs = new Map();
    const push = (e) => out.push(e);
    function line(l) {
      if (!l || l[0] !== '{') return;
      let o; try { o = JSON.parse(l); } catch (e) { return; }
      if (o.uuid) { if (seen.has(o.uuid)) return; seen.add(o.uuid); }
      const ts = o.timestamp || null;
      if (o.type === 'attachment' && o.attachment && o.attachment.type === 'queued_command' && o.attachment.origin && o.attachment.origin.kind === 'human' && typeof o.attachment.prompt === 'string') {
        push({ kind: 'prompt', ts, text: o.attachment.prompt, mid: true }); return;
      }
      if (o.type === 'system') {
        if (o.subtype === 'compact_boundary') push({ kind: 'marker', ts, name: 'Context compacted', text: '' });
        else if (o.subtype === 'api_error') { const c = clip(String(o.content || (o.error && o.error.message) || 'API error'), LIMITS.marker); push({ kind: 'marker', ts, name: 'API error', text: c.text, cut: c.cut, full: c.full, err: true }); }
        return;
      }
      if (o.type === 'user' && !o.isMeta) {
        const c = o.message && o.message.content;
        const texts = typeof c === 'string' ? [c] : [];
        if (Array.isArray(c)) {
          for (const b of c) {
            if (b.type === 'tool_result') {
              const r = clip(resultText(b.content), LIMITS.result);
              push({ kind: toolInputs.has(b.tool_use_id) ? 'answer' : 'result', ts, name: toolNames.get(b.tool_use_id) || 'result', text: r.text, cut: r.cut, full: r.full, err: !!b.is_error, asked: toolInputs.get(b.tool_use_id), answers: toolInputs.has(b.tool_use_id) ? answersOf(o, resultText(b.content)) : undefined });
            } else if (b.type === 'text') texts.push(b.text);
          }
        }
        for (const raw of texts) {
          // Pasted text arrives wrapped in <pasted_content> tags; the tags are not part of what was typed.
          const t = String(raw || '').replace(/<\/?pasted_content[^>]*>/g, '').trim();
          if (!t) continue;
          if (t.startsWith('This session is being continued')) { const m = clip(t, LIMITS.marker); push({ kind: 'marker', ts, name: 'Summary after compaction', text: m.text, cut: m.cut, full: m.full }); continue; }
          if (t.startsWith('[Request interrupted')) { push({ kind: 'marker', ts, name: 'Interrupted', text: '' }); continue; }
          if (t.startsWith('<') || t.startsWith('Caveat:')) continue;
          push({ kind: 'prompt', ts, text: t, mid: false });
        }
        return;
      }
      if (o.type === 'assistant') {
        const c = o.message && o.message.content;
        if (!Array.isArray(c)) return;
        for (const b of c) {
          if (b.type === 'text' && b.text && b.text.trim()) push({ kind: 'reply', ts, text: b.text });
          else if (b.type === 'thinking' && b.thinking && b.thinking.trim()) { const t = clip(b.thinking, LIMITS.think); push({ kind: 'think', ts, text: t.text, cut: t.cut, full: t.full }); }
          else if (b.type === 'tool_use') {
            toolNames.set(b.id, b.name);
            const s = clip(toolSummary(b.name, b.input), LIMITS.tool);
            push({ kind: 'tool', ts, name: b.name, text: s.text, cut: s.cut, full: s.full, input: DRAWN.has(b.name) ? b.input : undefined });
            if (b.name === 'AskUserQuestion') toolInputs.set(b.id, b.input);
          }
        }
      }
    }
    return { line, out };
  }
`public/index.html` also works on its own, opened straight from disk: the Sessions list is hidden and you open a `.jsonl` with the button or by dropping it on the page.

## Using it

- **Sessions** lists every transcript, newest first, with its first prompt, folder, branch, date, prompt count and size. Filter by text or by project.
- The left rail lists the turns. **Significant only** keeps the prompts that set a rule, a brief, a direction or a decision, plus the heavy turns; the star marks your own.
- Space plays or pauses; Left and Right step; Up and Down change turn. **End of turn** (or the End key) jumps to the last step of the current turn.
- Tool results and thinking are off by default; the checkboxes turn them on. Long text is clipped, and **Show all** opens the whole of it.

