// Reads one set, folding in any saved under the older name:size keys so they are not lost.
function loadSet(kind) {
  const set = new Set();
  try {
    const base = 'replay.' + kind + '.' + fileKey, old = [];
    for (let i = 0; i < localStorage.length; i++) { const k = localStorage.key(i); if (k === base || (k.startsWith(base + ':') && /^\d+$/.test(k.slice(base.length + 1)))) old.push(k); }
    old.forEach((k) => { try { JSON.parse(localStorage.getItem(k) || '[]').forEach((v) => set.add(v)); } catch (e) {} });
    if (old.some((k) => k !== base)) { localStorage.setItem(base, JSON.stringify([...set])); old.forEach((k) => { if (k !== base) localStorage.removeItem(k); }); }
  } catch (e) {}
  return set;
}
function loadStars() { stars = loadSet('stars'); marks = loadSet('marks'); }

