// `handle` (a FileSystemFileHandle, or a promise of one) lets the file be reopened from Recent.
async function loadFile(file, handle) {
  current = null; setHash('');
  // Keyed by name alone, as a session opened from the list is: a live transcript grows, and its size with it.
  await loadStream(file.stream(), file.size, file.name, file.name, file.name + '  (' + mb(file.size) + ')');
  let h = null; try { h = await handle; } catch (e) {}
  if (h && h.kind === 'file') addRecent({ kind: 'file', handle: h, name: file.name, size: file.size });
}

  await loadStream(r.body, size, s.file, s.file, whereOf(s) + '  ·  ' + fmtDate(s.modified) + '  (' + mb(size) + ')');
  addRecent({ kind: 'session', project: s.project, file: s.file, name: s.file, where: whereOf(s), size });
}

// ---------- recent files ----------
// Kept in IndexedDB, which can hold a file handle: a file picked with the browser's file picker (or dropped,
// in Chromium) reopens from here after the browser asks once for read access. A session from the list
// reopens through the server. Where the browser has neither, the list stays empty and the button hidden.
const RECENT_MAX = 15;
const byOpened = (a, b) => (a.opened < b.opened ? 1 : a.opened > b.opened ? -1 : 0);
const served = () => !$('browse').hidden;
function recentStore(mode, fn) {
  return new Promise((resolve, reject) => {
    const open = indexedDB.open('jsonlviewer', 1);
    open.onupgradeneeded = () => open.result.createObjectStore('recent', { keyPath: 'id' });
    open.onerror = () => reject(open.error);
    open.onsuccess = () => {
      const db = open.result; const tx = db.transaction('recent', mode); const req = fn(tx.objectStore('recent'));
      tx.oncomplete = () => { db.close(); resolve(req && req.result); };
      tx.onerror = tx.onabort = () => { db.close(); reject(tx.error); };
    };
  });
}
async function recentAll() { try { return ((await recentStore('readonly', (st) => st.getAll())) || []).sort(byOpened); } catch (e) { return []; } }
async function addRecent(entry) {
  try {
    const all = await recentAll();
    let same = null;
    for (const r of all) {
      if (entry.kind === 'session' ? r.kind === 'session' && r.project === entry.project && r.file === entry.file
        : r.kind === 'file' && r.handle && await r.handle.isSameEntry(entry.handle).catch(() => false)) { same = r; break; }
    }
    entry.id = same ? same.id : Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
    entry.opened = new Date().toISOString();
    entry.first = turns.length ? turns[0].prompt.slice(0, 300) : '';
    const drop = all.filter((r) => r.id !== entry.id).slice(RECENT_MAX - 1);
    await recentStore('readwrite', (st) => { st.put(entry); drop.forEach((r) => st.delete(r.id)); });
  } catch (e) {}
  showRecentButton();
}
async function showRecentButton() { $('recentBtn').hidden = !(await recentAll()).length; }
let recentItems = [];
async function renderRecent() {
  recentItems = await recentAll();
  const box = $('recentList');
  $('recentNote').textContent = window.showOpenFilePicker ? '' : 'This browser cannot reopen picked files; sessions from the list are kept.';
  if (!recentItems.length) { box.innerHTML = '<div class="empty">Nothing opened yet. Files you open with the button above, or drop on the page, are listed here.</div>'; return; }
  box.innerHTML = recentItems.map((r) => {
    const off = r.kind === 'session' && !served();
    return '<div class="recent-row" role="listitem"><button class="sess" data-id="' + esc(r.id) + '"' + (off ? ' disabled' : '') + '>'
      + '<span class="first">' + esc(r.first || r.name) + '</span>'
      + '<span class="meta"><span class="where">' + esc(r.kind === 'session' ? r.where : r.name) + '</span>'
      + '<span>' + (r.kind === 'session' ? 'from the sessions list' : 'local file') + '</span>'
      + '<span>opened ' + fmtDate(r.opened) + ' ' + fmtTime(r.opened) + '</span>' + (r.size ? '<span>' + mb(r.size) + '</span>' : '')
      + (off ? '<span class="gone">needs the server</span>' : '') + '</span></button>'
      + '<button class="rm" data-rm="' + esc(r.id) + '" aria-label="Remove from the list" title="Remove from the list">&times;</button></div>';
  }).join('');
}
async function openRecent(r) {
  if (r.kind === 'session') {
    const s = sessionList.find((x) => x.project === r.project && x.file === r.file) || { project: r.project, file: r.file, size: r.size, modified: r.opened, cwd: r.where };
    return openSession(s);
  }
  try {
    // Read access is granted per browser session; asking needs this click, so it comes first.
    if ((await r.handle.queryPermission({ mode: 'read' })) !== 'granted' && (await r.handle.requestPermission({ mode: 'read' })) !== 'granted') return;
    await loadFile(await r.handle.getFile(), r.handle);
  } catch (e) { $('src').textContent = 'Could not open ' + r.name + ' (' + (e.name === 'NotFoundError' ? 'it has been moved or deleted' : e.message) + ')'; }
}
// The browser's own file dialog where it can return a handle; the plain file input elsewhere.
async function pickFile() {
  if (!window.showOpenFilePicker) { $('file').click(); return; }
  let h;
  try { [h] = await window.showOpenFilePicker({ id: 'jsonl', types: [{ description: 'Claude Code transcripts', accept: { 'application/x-ndjson': ['.jsonl'], 'application/json': ['.json'] } }] }); } catch (e) { return; }
  try { await loadFile(await h.getFile(), h); } catch (e) { $('src').textContent = 'Could not open ' + h.name + ' (' + e.message + ')'; }
}
function openRecentDialog() { const d = $('recent'); if (!d.open) d.showModal(); renderRecent(); }
$('recentBtn').onclick = openRecentDialog;
$('recentClose').onclick = () => $('recent').close();
$('recentPick').onclick = () => { $('recent').close(); pickFile(); };
$('recentClear').onclick = async () => { try { await recentStore('readwrite', (st) => st.clear()); } catch (e) {} renderRecent(); showRecentButton(); };
$('recent').addEventListener('click', (e) => { if (e.target === $('recent')) $('recent').close(); });
$('recentList').onclick = async (e) => {
  const rm = e.target.closest('[data-rm]');
  if (rm) { try { await recentStore('readwrite', (st) => st.delete(rm.dataset.rm)); } catch (err) {} renderRecent(); showRecentButton(); return; }
  const b = e.target.closest('.sess'); if (!b || b.disabled) return;
  const r = recentItems.find((x) => x.id === b.dataset.id); if (!r) return;
  $('recent').close(); openRecent(r);
};

