window.addEventListener('drop', (e) => {
  e.preventDefault(); dragDepth = 0; $('drop').hidden = true;
  const f = e.dataTransfer.files[0]; if (!f) return;
  // The handle has to be asked for while the drop event is still running; it resolves later.
  const item = [...e.dataTransfer.items].find((i) => i.kind === 'file');
  let handle = null; try { if (item && item.getAsFileSystemHandle) handle = item.getAsFileSystemHandle(); } catch (err) {}
  loadFile(f, handle);
});

  showRecentButton();
  startWithServer();
})();

