async page => {
  await page.evaluate(() => document.getElementById('picker').close());
  const before = await page.evaluate(() => document.getElementById('recentBtn').hidden);
  // A real FileSystemFileHandle, from the origin-private file system, standing in for the picker's.
  await page.evaluate(async () => {
    const root = await navigator.storage.getDirectory();
    const h = await root.getFileHandle('picked.jsonl', { create: true });
    const w = await h.createWritable();
    await w.write(JSON.stringify({ type: 'user', uuid: 'p1', timestamp: '2026-09-01T09:00:00Z', message: { role: 'user', content: 'Picked file prompt' } }) + '\n');
    await w.close();
    window.showOpenFilePicker = async () => [h];
  });
  await page.click('#pick');
  await page.waitForTimeout(500);
  const afterPick = await page.evaluate(() => ({ src: document.getElementById('src').textContent, btn: document.getElementById('recentBtn').hidden }));
  // Open a server session through the Sessions list.
  await page.click('#browse'); await page.waitForTimeout(300);
  await page.click('#sessionList .sess'); await page.waitForTimeout(500);
  await page.click('#pick'); await page.waitForTimeout(500); // pick the same file again: must not duplicate
  await page.click('#recentBtn'); await page.waitForTimeout(300);
  const rows = await page.evaluate(() => [...document.querySelectorAll('#recentList .sess')].map((b) => b.innerText.replace(/\n/g, ' | ')));
  // Reopen the session entry (second row) from Recent.
  await page.click('#recentList .recent-row:nth-child(2) .sess'); await page.waitForTimeout(500);
  const reopened = await page.evaluate(() => document.getElementById('src').textContent);
  return JSON.stringify({ before, afterPick, rows, reopened }, null, 1);
}
EOF
