    // Step until the feed would overflow, then stop one short, so the prompt stays at the top.
    const n = await page.evaluate(() => {
      const f = document.getElementById('feed'); const k = (key) => document.body.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true }));
      let steps = 0;
      for (; steps < 60; steps++) { k('ArrowRight'); if (f.scrollHeight > f.clientHeight + 4) { k('ArrowLeft'); break; } }
      f.scrollTop = 0; document.getElementById('turns').scrollTop = 0;
      return steps;
    });
    await page.waitForTimeout(200);
    await page.screenshot({ path: `real-${t + 1}.png` });
    out.push(t + 1 + ':' + n);
  }
  return out.join(' ');
}
