async function copyText(text) {
  try { await navigator.clipboard.writeText(text); return true; } catch (e) {}
  // Where the Clipboard API is refused, a selected textarea and the older copy command still work.
  const t = document.createElement('textarea'); t.value = text; t.setAttribute('readonly', ''); t.style.position = 'fixed'; t.style.opacity = '0';
  document.body.appendChild(t); t.select();
  let ok = false; try { ok = document.execCommand('copy'); } catch (e) {}
  t.remove(); return ok;
}
$('copyPath').onclick = async () => {
  if (!currentPath) return;
  const b = $('copyPath'); const ok = await copyText(currentPath);
  b.textContent = ok ? 'Copied' : 'Could not copy'; b.classList.toggle('done', ok);
  clearTimeout(copiedTimer); copiedTimer = setTimeout(() => { b.textContent = 'Copy path'; b.classList.remove('done'); }, 1500);
};

