// Without the server (a hosted copy, or the page opened from disk) the visitor has to find their own
// transcripts, in a folder most file dialogs hide.
function showWhere() {
  const p = String((navigator.userAgentData && navigator.userAgentData.platform) || navigator.platform || '');
  const win = /win/i.test(p), mac = /mac/i.test(p);
  const dir = win ? '%USERPROFILE%\\.claude\\projects' : '~/.claude/projects';
  const hidden = mac ? ' (the folder is hidden; press &#8984;&#8679;. in the file dialog to show it)' : '';
  $('where').innerHTML = 'Your Claude Code transcripts are in <code>' + esc(dir) + '</code>' + hidden + '. The file is read in your browser and never uploaded.';
  $('where').hidden = false;
  $('pick').title = 'Transcripts are in ' + dir;
}
// server.js only ever listens on the loopback address, so a page served from anywhere else has no server to ask.
const loopback = /^(127\.0\.0\.1|localhost|\[::1\])$/.test(location.hostname);
async function startWithServer() {
  if (!loopback || (location.protocol !== 'http:' && location.protocol !== 'https:')) { showWhere(); return; }
  try { await fetchSessions(); } catch (e) { showWhere(); return; }
  $('browse').hidden = false; serverBookmarks = true;

